    stagePaths.Add(stagePath);
    await WriteContentAsync(stagePath, request.WriteContentAsync, cancellationToken).ConfigureAwait(false);
    var bytes = new FileInfo(stagePath).Length;
    var artifact = new ReportArtifact(
        artifactId,
